// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CertificateRegistry
 * @dev Contrato para registrar y verificar certificados en la blockchain
 * Este contrato almacena hashes SHA-256 de certificados emitidos
 */
contract CertificateRegistry {
    // Estructura para almacenar información del certificado
    struct Certificate {
        bytes32 hash;
        uint256 timestamp;
        address institution;
        bool revoked;
        uint256 revokedAt;
    }
    
    // Mapping para almacenar certificados por su hash único
    mapping(bytes32 => Certificate) public certificates;
    
    // Mapping para rastrear qué institución emitió qué certificados
    mapping(address => bytes32[]) public institutionCertificates;
    
    // Eventos para notificar acciones
    event CertificateRegistered(
        bytes32 indexed certificateHash,
        address indexed institution,
        uint256 timestamp
    );
    
    event CertificateRevoked(
        bytes32 indexed certificateHash,
        address indexed institution,
        uint256 timestamp
    );
    
    // Variable para el owner del contrato (opcional)
    address public owner;
    
    constructor() {
        owner = msg.sender;
    }
    
    /**
     * @dev Registrar un nuevo certificado en la blockchain
     * @param certificateHash El hash SHA-256 del certificado
     * @return success True si el registro fue exitoso
     */
    function registerCertificate(bytes32 certificateHash) public returns (bool) {
        // Verificar que el certificado no exista ya
        require(
            certificates[certificateHash].timestamp == 0,
            "Certificate already registered"
        );
        
        // Registrar el certificado
        certificates[certificateHash] = Certificate({
            hash: certificateHash,
            timestamp: block.timestamp,
            institution: msg.sender,
            revoked: false,
            revokedAt: 0
        });
        
        // Agregar a la lista de certificados de la institución
        institutionCertificates[msg.sender].push(certificateHash);
        
        // Emitir evento
        emit CertificateRegistered(certificateHash, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @dev Verificar si un certificado está registrado
     * @param certificateHash El hash SHA-256 del certificado
     * @return exists True si el certificado existe
     * @return timestamp Timestamp de registro
     * @return institution Dirección de la institución que lo emitió
     * @return revoked Si el certificado ha sido revocado
     */
    function verifyCertificate(bytes32 certificateHash)
        public
        view
        returns (
            bool exists,
            uint256 timestamp,
            address institution,
            bool revoked
        )
    {
        Certificate memory cert = certificates[certificateHash];
        exists = cert.timestamp > 0;
        timestamp = cert.timestamp;
        institution = cert.institution;
        revoked = cert.revoked;
    }
    
    /**
     * @dev Revocar un certificado
     * @param certificateHash El hash SHA-256 del certificado a revocar
     * @return success True si la revocación fue exitosa
     */
    function revokeCertificate(bytes32 certificateHash) public returns (bool) {
        Certificate storage cert = certificates[certificateHash];
        
        // Verificar que el certificado exista
        require(cert.timestamp > 0, "Certificate does not exist");
        
        // Verificar que sea la institución que lo emitió
        require(
            cert.institution == msg.sender,
            "Only issuing institution can revoke"
        );
        
        // Verificar que no esté ya revocado
        require(!cert.revoked, "Certificate already revoked");
        
        // Revocar el certificado
        cert.revoked = true;
        cert.revokedAt = block.timestamp;
        
        // Emitir evento
        emit CertificateRevoked(certificateHash, msg.sender, block.timestamp);
        
        return true;
    }
    
    /**
     * @dev Obtener todos los certificados de una institución
     * @param institutionAddress Dirección de la institución
     * @return Array de hashes de certificados
     */
    function getInstitutionCertificates(address institutionAddress)
        public
        view
        returns (bytes32[] memory)
    {
        return institutionCertificates[institutionAddress];
    }
}

